import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"64、【未濟】 坎下離上","description":"子夏易傳 - 64、【未濟】 坎下離上","frontmatter":{"title":"64、【未濟】 坎下離上","description":"子夏易傳 - 64、【未濟】 坎下離上"},"headers":[],"relativePath":"classics/zixia/066.md","filePath":"classics/zixia/066.md"}'),i={name:"classics/zixia/066.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_64、【未濟】-坎下離上" tabindex="-1">64、【未濟】 坎下離上 <a class="header-anchor" href="#_64、【未濟】-坎下離上" aria-label="Permalink to “64、【未濟】 坎下離上”">​</a></h1><p>卦辭：未濟，亨。小狐汔濟，濡其尾，無攸利。</p><p>彖曰：未濟亨，柔得中也。小狐汔濟，未出中也。濡其尾，無攸利，不續終也。雖不當位，剛柔應也。</p><p>子夏：柔得中，不當位，未?濟也，而□其變矣。剛近濟在於險中，力小形微，濡其尾，無攸利，不?續其終。下非所濟逺也。剛柔而同力，故有終通之道焉。</p><p>象曰：火在水上，未濟。君子以慎辨物居方。</p><p>子夏：火上水下，各守其所，雖未濟而各保其安也。君子明愼辨物，而使各安其所，則致之而得宜用之，而得當也。</p><p>初六，濡其尾，吝。</p><p>象曰：濡其尾，亦不知極也。</p><p>子夏：以柔而濟於險，初始渉者也。近淺猶濡尾矣，況其深必不濟矣。不知力之極也，可惜也已。</p><p>九二，曵其輪，貞吉。</p><p>象曰：九二貞吉，中以行正也。</p><p>子夏：居得險中，動而應主，剛德不邪而?濟也，故曵輪。載險而當之矣，故正吉也。</p><p>六三，未濟徵兇，利渉大川。</p><p>象曰：未濟徵兇，位不當也。</p><p>子夏：力小失位，逺何為，附於二則險自濟也。</p><p>九四，貞吉，悔亡。震用伐鬼方，三年有賞於大國。</p><p>象曰：貞吉悔亡，志行也。</p><p>子夏：未濟徵兇，柔居中，力小不?濟也。有委任之道焉，未濟當位，志在乎濟，而奉其上得正之吉也。而遂其志焉。何逼近之悔乎，將盡力以功，震其未濟，故伐鬼方，三年乃克，而受國矣。初以勤奉主，終以功獲賞，有終濟之義也。</p><p>六五，貞吉無悔。君子之光，有孚，吉。</p><p>象曰：君子之光，其暉吉也。</p><p>子夏：柔得中正之吉，無其悔也。志在乎濟，授之以?任之，無疑以至於終濟，可謂君子之光煥乎輝發矣。信有中正之吉哉。</p><p>上九，有孚，於飲酒，無咎。濡其首，有孚，失是。</p><p>象曰：飲酒濡首，亦不知節也。</p><p>子夏：滿者自覆，謙者自益，非天之所為也。夫以未濟之初志存，而不懈以至於終濟，而信有其樂也，亦何咎哉。樂極志滿，道斯反矣，故濡其首，信失其樂哉。夫將濟者，力之及也。濟非大順而致也，力以取之，順以守之，乃得其久。旣濟而盈，將有覆矣。君子可無懼乎。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
